import Link from 'next/link';
import { requireAdmin } from '@/lib/admin-auth';
import { supabaseAdmin } from '@/lib/supabase-server';
import {
  PaymentEventStatusBadge,
  PaymentChannelBadge,
  PAYMENT_EVENT_STATUS_MAP,
} from '@/lib/admin-helpers';

/**
 * /admin/payment-events 支付回调事件
 *
 * 改版 v2 (2026-06-09):
 *   - 改用 @/lib/admin-helpers 共享 PaymentEventStatusBadge / PaymentChannelBadge
 *   - 删除本地 STATUS_BADGES / CHANNEL_BADGES
 *   - 添加 leading-tight-cn / leading-relaxed-cn / tabular-nums
 *   - Tab 链接加 aria-current="page" (选中状态)
 *   - 表格加 aria-label + <th scope="col">
 *   - 添加 pb-safe
 */

export const dynamic = 'force-dynamic';

async function loadEvents(status?: string) {
  if (!supabaseAdmin) return [];
  let query = supabaseAdmin
    .from('payment_events')
    .select('id, channel, external_event_id, order_no, status, error_message, attempts, processed_at, created_at')
    .order('created_at', { ascending: false })
    .limit(100);
  if (status && status !== 'all') {
    query = query.eq('status', status);
  }
  const { data } = await query;
  return data || [];
}

export default async function PaymentEventsPage({
  searchParams,
}: {
  searchParams: Promise<{ status?: string }>;
}) {
  const auth = await requireAdmin();
  if (!auth.authenticated) {
    return <div className="leading-relaxed-cn">无权访问</div>;
  }

  const { status } = await searchParams;
  const events = await loadEvents(status);

  // 计数
  const counts = await supabaseAdmin
    ?.from('payment_events')
    .select('status', { count: 'exact', head: false });
  const statusCounts: Record<string, number> = {};
  for (const e of counts?.data || []) {
    statusCounts[e.status] = (statusCounts[e.status] || 0) + 1;
  }
  const totalCount = counts?.count || 0;

  const currentStatus = status || 'all';

  return (
    <div className="space-y-6 pb-safe">
      <div>
        <h1 className="text-2xl font-bold text-slate-800 mb-1 leading-tight-cn">
          <span aria-hidden>💰 </span>支付回调事件
        </h1>
        <p className="text-sm text-slate-600 leading-relaxed-cn">
          微信 / 支付宝回调事件流水. 失败事件可手动重试.
        </p>
      </div>

      {/* 状态筛选 tab */}
      <div
        className="flex flex-wrap gap-2"
        role="tablist"
        aria-label="事件状态过滤"
      >
        {[
          { v: 'all', l: '全部', n: totalCount },
          { v: 'received', l: '待处理', n: statusCounts.received || 0 },
          { v: 'processed', l: '已处理', n: statusCounts.processed || 0 },
          { v: 'failed', l: '失败', n: statusCounts.failed || 0 },
          { v: 'ignored', l: '忽略', n: statusCounts.ignored || 0 },
        ].map((tab) => {
          const isActive = currentStatus === tab.v;
          return (
            <Link
              key={tab.v}
              href={`/admin/payment-events?status=${tab.v}`}
              role="tab"
              aria-selected={isActive}
              aria-current={isActive ? 'page' : undefined}
              className={`px-4 py-1.5 rounded-full text-sm font-medium focus-ring-visible leading-tight-cn ${
                isActive
                  ? 'bg-amber-500 text-white'
                  : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
              }`}
            >
              {tab.l} (<span className="tabular-nums">{tab.n}</span>)
            </Link>
          );
        })}
      </div>

      <div className="bg-white rounded-xl shadow-sm overflow-hidden">
        {events.length === 0 ? (
          <div className="p-12 text-center text-slate-400 text-sm leading-relaxed-cn">
            暂无 {status && status !== 'all' ? PAYMENT_EVENT_STATUS_MAP[status]?.label : ''} 事件
          </div>
        ) : (
          <table className="w-full text-sm" aria-label="支付回调事件列表">
            <thead className="bg-slate-50 text-slate-600 text-xs uppercase">
              <tr>
                <th scope="col" className="px-4 py-2 text-left">渠道</th>
                <th scope="col" className="px-4 py-2 text-left">订单号</th>
                <th scope="col" className="px-4 py-2 text-left">外部 ID</th>
                <th scope="col" className="px-4 py-2 text-left">状态</th>
                <th scope="col" className="px-4 py-2 text-right">重试</th>
                <th scope="col" className="px-4 py-2 text-left">错误</th>
                <th scope="col" className="px-4 py-2 text-right">时间</th>
              </tr>
            </thead>
            <tbody>
              {events.map((e) => (
                <tr key={e.id} className="border-t border-slate-100 hover:bg-slate-50">
                  <td className="px-4 py-2">
                    <PaymentChannelBadge channel={e.channel} />
                  </td>
                  <td className="px-4 py-2 font-mono text-xs tabular-nums">
                    {e.order_no || '—'}
                  </td>
                  <td className="px-4 py-2 font-mono text-xs text-slate-500 truncate max-w-[200px]">
                    {e.external_event_id}
                  </td>
                  <td className="px-4 py-2">
                    <PaymentEventStatusBadge status={e.status} />
                  </td>
                  <td className="px-4 py-2 text-right text-slate-500 tabular-nums">
                    {e.attempts > 0 ? `${e.attempts}x` : '—'}
                  </td>
                  <td className="px-4 py-2 text-xs text-red-600 max-w-[200px] truncate leading-tight-cn">
                    {e.error_message || '—'}
                  </td>
                  <td className="px-4 py-2 text-right text-xs text-slate-500 tabular-nums">
                    {new Date(e.created_at).toLocaleString('zh-CN', { hour12: false })}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div
        className="bg-blue-50 border border-blue-200 rounded-xl p-4 text-sm text-blue-900 leading-relaxed-cn"
        role="note"
        aria-label="事件状态说明"
      >
        <div className="font-semibold mb-2 leading-tight-cn">
          <span aria-hidden>📖 </span>事件状态说明
        </div>
        <ul className="space-y-1 text-blue-800">
          <li>
            <span aria-hidden>• </span>
            <strong>received</strong>: 已记录, 待处理 (异常: 重试多次仍未处理)
          </li>
          <li>
            <span aria-hidden>• </span>
            <strong>processed</strong>: 业务处理成功, 订单已更新为 paid
          </li>
          <li>
            <span aria-hidden>• </span>
            <strong>failed</strong>: 业务处理失败 (订单不存在 / 金额不一致 / DB 错误)
          </li>
          <li>
            <span aria-hidden>• </span>
            <strong>ignored</strong>: 主动忽略 (如 trade_state=REFUND)
          </li>
        </ul>
      </div>
    </div>
  );
}
